import React, { useState } from 'react';
import './About.css';

const About = () => {
    const [activeTab, setActiveTab] = useState('org');

    // Data mapped directly from your provided HTML content
    const renderContent = () => {
        switch (activeTab) {
            case 'org':
                return (
                    <div className="tab-pane fade-in">
                        <section className="portfolio-section">
                            <div className="section-title">
                                <h2>Organization Portfolio</h2>
                                <p>Your trusted partner in financial empowerment</p>
                            </div>
                            <div className="stats-grid">
                                <div className="stat-card"><h3>5.71 Arba</h3><p>Total Loan</p></div>
                                <div className="stat-card"><h3>1.33 Arba</h3><p>Total Savings</p></div>
                                <div className="stat-card"><h3>9,604</h3><p>Total Centers</p></div>
                                <div className="stat-card"><h3>1,05,820</h3><p>Total Members</p></div>
                            </div>
                        </section>
                    </div>
                );
            case 'ovm':
                return (
                    <div className="tab-pane fade-in">
                        <div className="ovm-grid">
                            <div className="info-card"><h3>Objective</h3><p>ILBSL aims to empower Nepal’s underserved communities by fostering self-reliance and independence, contributing to rural social development through self-employment and enhanced social awareness.</p></div>
                            <div className="info-card"><h3>Vision</h3><p>To build a sustainable and inclusive society by promoting economic independence among Nepal’s marginalized populations, primarily through self-employment and social empowerment.</p></div>
                            <div className="info-card"><h3>Mission</h3><p>To provide sustainable microfinance services to needy and underserved families across Nepal, supporting their journey toward financial stability and growth.</p></div>
                            <div classname='info-card'></div>
                        </div>
                    </div>
                );
            case 'capital':
                return (
                    <div className="tab-pane fade-in">
                        <div className="stats-grid">
                            <div className="stat-card"><h3>Rs. 700M</h3><p>Authorized Capital</p></div>
                            <div className="stat-card"><h3>Rs. 497.41M</h3><p>Paid-up Capital</p></div>
                        </div>
                    </div>
                );
            case 'board':
                return (
                    <div className="tab-pane fade-in">
                        <div className="people-grid">
                            <div className="person-card">
                                <img src="/assets/Bishnu_Sir.jpg" alt="Chairman" />
                                <h3>Mr. Bishnu Kumar Ghimire</h3>
                                <p className="role">Chairman</p>
                            </div>
                            <div className="person-card">
                                <img src="/assets/Ram_Sir_photo.jpg" alt="Director" />
                                <h3>Mr. Ram Krishna Dangol</h3>
                                <p className="role">Director</p>
                            </div>
                        </div>
                    </div>
                );
            case 'ceo':
                return (
                    <div className="tab-pane fade-in">
                        <div className="ceo-card-container">
                            <div className="ceo-img-wrapper">
                                <img src="/assets/ceo-sir.jpg" alt="CEO" />
                            </div>
                            <div className="ceo-text">
                                <h3>Gyanishor Panta</h3>
                                <h4>Chief Executive Officer</h4>
                                <p>"Our mission is to bridge the gap in financial inclusion for Nepal's rural communities."</p>
                            </div>
                        </div>
                    </div>
                );
            case 'management':
                return (
                    <div className="tab-pane fade-in">
                        <div className="people-grid">
                            <div className="person-card"><h3>Krishna Prasad Khanal</h3><p>Internal Audit</p></div>
                            <div className="person-card"><h3>Amarnath Sedhai</h3><p>Credit Dept</p></div>
                            <div className="person-card"><h3>Subash Kumar Gupta</h3><p>IT Dept</p></div>
                            <div className="person-card"><h3>Ritu Baniya</h3><p>Finance/Ops</p></div>
                        </div>
                    </div>
                );
            case 'support':
                return (
                    <div className="tab-pane fade-in">
                        <div className="support-grid">
                            <div className="dept-card">
                                <h4>IT Department</h4>
                                <p>Prabin Kafle: Ext-109</p>
                                <p>Susmita Adhikari: Ext-107</p>
                            </div>
                            <div className="dept-card">
                                <h4>Finance Department</h4>
                                <p>Padam Raj Sigdel: Ext-126</p>
                                <p>Dhiraj Chaudhary: Ext-102</p>
                            </div>
                        </div>
                    </div>
                );
            default: return null;
        }
    };

    return (
        <div className="about-container">
            <div className="about-hero">
                <h1>About Us</h1>
                <div className="underline"></div>
            </div>

            <nav className="about-tabs">
                {['org', 'ovm', 'capital', 'board', 'ceo', 'management', 'support'].map((tab) => (
                    <button
                        key={tab}
                        className={activeTab === tab ? 'tab-btn active' : 'tab-btn'}
                        onClick={() => setActiveTab(tab)}
                    >
                        {tab.toUpperCase().replace('ORG', 'Organization').replace('OVM', 'Vision')}
                    </button>
                ))}
            </nav>

            <main className="content-area">
                {renderContent()}
            </main>
        </div>
    );
};

export default About;
